      if (path.endsWith('/overview')) return reply(route, { counts: {}, priorities: [] });
      if (path.endsWith('/landed-costs')) return reply(route, opts.history ?? []);
      if (path.endsWith('/variants')) return reply(route, opts.variants ?? []);
