  await page.route('**/stock', r => r.request().isNavigationRequest() ? r.fallback() : reply(r, opts.stockUnavailable ? {message:'Fixture stock unavailable'} : opts.stock ?? stock, opts.stockUnavailable ? 503 : 200));
